const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let prefs={place:'Porto d’Ascoli',places:['Porto d’Ascoli'],large:false};try{prefs={...prefs,...JSON.parse(localStorage.getItem('scudo-preferences')||'{}')}}catch{}
let filter='Tutti',radar='Pioggia',reports=[],comments={},likes=new Set(),following=new Set();const posts=[{id:1,name:'Elena · esempio',type:'Pioggia',text:'Qui la pioggia è diminuita. Voi cosa osservate nella vostra zona?',area:'Centro',time:'Esempio di osservazione'},{id:2,name:'Paolo · esempio',type:'Grandine',text:'Come si segnala la dimensione della grandine senza confonderla con l’intensità della pioggia?',area:'Community meteo',time:'Esempio di domanda'}];
function save(){try{localStorage.setItem('scudo-preferences',JSON.stringify(prefs))}catch{toast('Preferenze non salvabili su questo browser.')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(title,body,fn){window.speechSynthesis?.cancel();$('#dialogForm button[type=submit]').textContent='Salva';$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialogForm').onsubmit=e=>{e.preventDefault();if(fn()!==false)$('#dialog').close()};$('#dialog').showModal()}$('#close').onclick=()=>$('#dialog').close();
function locationDialog(){modal('Quale zona vuoi seguire?',`<label class="field"><span>Località</span><input id="newPlace" required maxlength="60" value="${esc(prefs.place)}"></label><p class="small">Cambia il nome della zona nella demo. Non carica previsioni reali.</p>`,()=>{const v=$('#newPlace').value.trim();if(!v)return false;prefs.place=v;if(!prefs.places.includes(v))prefs.places.push(v);save();render()})}$('#place').onclick=locationDialog;
function postCard(p){return `<article class="card"><div class="post-head"><div class="avatar">${esc(p.name[0])}</div><div><b>${esc(p.name)}</b><p class="meta">${esc(p.area)} · ${esc(p.time)}</p></div></div><p class="post-text">${esc(p.text)}</p><span class="tag">${esc(p.type)} · Non verificato</span><div class="post-actions actions"><button data-like="${p.id}">${likes.has(p.id)?'✓ Utile':'♡ Utile'}</button><button data-comment="${p.id}">Commenta${comments[p.id]?.length?' ('+comments[p.id].length+')':''}</button><button data-follow="${p.id}">${following.has(p.id)?'✓ Seguito':'Segui'}</button><button data-flag="${p.id}" aria-label="Segnala contenuto">Segnala</button></div><div class="comments">${(comments[p.id]||[]).map(t=>`<p><b>Tu · prova locale</b><br>${esc(t)}</p>`).join('')}</div></article>`}
function originalHome(){return `<div class="eyebrow">Il tuo meteo, senza complicazioni</div><h1>${esc(prefs.place)}</h1><p>Oggi · anteprima con dati di esempio</p><section class="card weather"><span class="tag">PREVISIONE DIMOSTRATIVA</span><div class="temperature"><div><strong>22°</strong><p>Parzialmente nuvoloso</p></div><span class="sun" aria-hidden="true">☀</span></div><p>Min 17° · Max 24° · Percepiti 22°</p><div class="note"><b>Per le allerte, serve una fonte reale.</b><p>Il servizio non è ancora collegato. Nessun rischio può essere escluso da questa schermata.</p></div><a class="button wide" href="#radar">Apri il radar</a></section><section class="card"><h2>Le prossime ore</h2><span class="meta">Valori di esempio</span><div class="hours">${['Ora','15:00','16:00','17:00','18:00'].map((h,i)=>`<div><span>${h}</span><b>${[22,23,24,22,20][i]}°</b><span>${[10,20,35,45,25][i]}% pioggia</span></div>`).join('')}</div><div class="row"><span>Vento</span><b>12 km/h · NE</b></div><div class="row"><span>Umidità</span><b>64%</b></div><div class="row"><span>Indice UV</span><b>4 · moderato</b></div><div class="row"><span>Alba / tramonto</span><b>06:40 / 19:25</b></div></section><div class="section-head"><h2>Vicino a te</h2><a href="#community">Apri community →</a></div>${postCard(posts[0])}<section class="card"><h2>I tuoi luoghi e le tue persone</h2><p>Organizza le zone che vuoi seguire. Gli avvisi automatici saranno disponibili dopo il collegamento dei dati.</p><div class="actions"><a href="#profilo" class="button">Gestisci luoghi</a><a href="#ripari" class="button">Esplora ripari</a></div></section><section class="card"><h2>Previsioni dei prossimi giorni</h2><p class="small">Solo esempi, non un bollettino.</p>${['Domani','Dopodomani','Tra 3 giorni'].map((x,i)=>`<div class="row"><b>${x}</b><span>${['Nuvoloso','Pioggia','Sereno'][i]}</span><span>${[18,16,17][i]}° / ${[23,21,25][i]}°</span></div>`).join('')}</section>`}
function home(){
 const more=originalHome().split('<section class="card"><h2>Le prossime ore</h2>')[1];
 return `<div class="home-heading"><div><span class="eyebrow">Il meteo di casa tua</span><h1>${esc(prefs.place)}</h1></div><button data-access class="access-pill" aria-label="Apri le opzioni di lettura">Aa <span>Leggibilità</span></button></div>
 <section class="card weather weather-new" aria-label="Esempio di previsione"><div class="weather-top"><span class="weather-label">OGGI</span><span class="tag">Dati di esempio</span></div><div class="temperature"><div><strong>22<span>°</span></strong><p>Parzialmente nuvoloso</p></div><span class="sun" aria-hidden="true">☀</span></div><div class="weather-bottom"><span>Minima <b>17°</b></span><span>Massima <b>24°</b></span><span>Percepiti <b>22°</b></span></div></section>
 <div class="service-note"><b>Allerte non disponibili</b><span>Il meteo reale non è collegato. Non usare questi esempi per valutare un rischio.</span></div>
 <div class="quick-links"><a href="#radar"><b>◎</b><span>Vedi radar<small>Pioggia e grandine</small></span></a><a href="#segnala"><b>＋</b><span>Segnala<small>Racconta cosa vedi</small></span></a></div>
 <div class="view-controls"><button data-simple aria-pressed="${!!prefs.simple}">${prefs.simple?'✓ Modalità essenziale':'Modalità essenziale'}</button><button data-read>Ascolta il riepilogo</button></div>
 ${prefs.simple?`<div class="section-head"><h2>Le persone della tua zona</h2></div><section class="card"><p>Fai una domanda o prova a condividere un’osservazione.</p><a class="button wide" href="#community">Apri la community</a></section><button class="wide" data-simple>Mostra anche ore e dettagli</button>`:`<details class="card forecast-details" open><summary>Le prossime ore e i dettagli <span>↓</span></summary><section><h2 class="sr-only">Le prossime ore</h2>${more.split('</section>')[0]}</section></details>${more.slice(more.indexOf('</section>')+10)}`}
 <section class="invite-card"><span class="eyebrow">Una community comincia da due persone</span><h2>Il tuo quartiere, più vicino.</h2><p>Invita qualcuno a conoscere SCUDO. Nessun invio automatico e nessuna catena obbligatoria.</p><button class="button" data-invite>Prepara un invito</button><span class="small">Anteprima privata: il link non concede accesso.</span></section>`;
}

function radarView(){return `<h1>Radar</h1><p>Pioggia, temporali e grandine, in una schermata dedicata.</p><div class="filters">${['Pioggia','Temporali','Grandine'].map(x=>`<button data-radar="${x}" class="${radar===x?'selected':''}" aria-pressed="${radar===x}">${x}</button>`).join('')}</div><section class="card"><h2>${radar} · ${esc(prefs.place)}</h2><div class="empty"><div class="symbol">◎</div><h3>Radar non collegato</h3><p>Nessuna immagine disponibile. Una mappa vuota non significa assenza di maltempo.</p><span class="tag">Ultimo aggiornamento: non disponibile</span></div><div class="note"><b>${radar==='Grandine'?'Pioggia intensa non significa automaticamente grandine.':'Una previsione non è un’osservazione.'}</b><p>Mostreremo fonte, ora del dato e limiti di copertura prima di attivare questo servizio.</p></div></section><section class="card"><h2>Tre informazioni diverse</h2><div class="row"><b>Radar</b><span>Rilevazioni strumentali</span></div><div class="row"><b>Community</b><span>Osservazioni non necessariamente verificate</span></div><div class="row"><b>Allerta ufficiale</b><span>Bollettino dell’ente competente</span></div></section><a class="button" href="#community">Vedi le osservazioni di esempio</a>`}
function reportView(){return `<h1>Segnala cosa osservi</h1><p>Un contributo semplice, utile per chi ti è vicino.</p><form class="card" id="reportForm"><span class="tag">Prova locale · nessun invio pubblico</span><label class="field"><span>Cosa vuoi segnalare?</span><select id="kind">${['Pioggia','Grandine','Vento','Allagamento','Cielo sereno'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Zona indicativa</span><input id="area" value="${esc(prefs.place)}" required maxlength="70"></label><label class="field"><span>Cosa sta succedendo?</span><textarea id="description" placeholder="Descrivi ciò che vedi, senza inserire indirizzi privati o dati personali." required maxlength="500"></textarea></label><label class="check"><input type="checkbox" required><span>Sto segnalando da un luogo sicuro e non sto guidando.</span></label><button class="button wide">Aggiungi alla community di prova</button><p class="small">La segnalazione rimane solo in questa sessione. Non raggiunge cittadini o soccorsi.</p></form>`}
function community(){const visible=[...reports,...posts].filter(p=>filter==='Tutti'||filter==='Seguiti'&&following.has(p.id)||p.type===filter);return `<h1>La tua community</h1><p>Osservazioni, domande e persone della tua zona.</p><a class="button" href="#segnala">＋ Condividi un’osservazione</a><div class="filters">${['Tutti','Seguiti','Pioggia','Grandine'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><p class="small">Profili di esempio. Commenti, follow e reazioni sono prove locali e si azzerano ricaricando.</p>${visible.length?visible.map(postCard).join(''):'<div class="empty"><h2>Ancora nessun contenuto</h2><p>Cambia filtro o aggiungi una segnalazione di prova.</p></div>'}<section class="card"><h2>Una stanza per ogni evento</h2><p>Le stanze locali raggrupperanno osservazioni sullo stesso temporale. Non c’è una stanza reale attiva in questa demo.</p><button data-invite>Prepara un invito per un amico</button><p class="small">L’anteprima è privata: il link non concede accesso ad altre persone.</p></section>`}
function profile(){return `<h1>Il tuo spazio</h1><p>Preferenze salvate su questo dispositivo, senza account.</p><section class="card"><h2>Luoghi da seguire</h2>${prefs.places.map((p,i)=>`<div class="row"><span>${esc(p)}</span>${p===prefs.place?'<span class="tag">Zona attuale</span>':`<button data-remove="${i}">Rimuovi</button>`}</div>`).join('')}<button class="button" id="addPlace">＋ Aggiungi luogo</button></section><section class="card"><h2>SCUDO, come lo preferisci</h2><p>Dimensione del testo, contrasto e modalità essenziale.</p><button data-access class="button">Personalizza la lettura</button></section><section class="card"><h2>Notifiche e persone care</h2><p>Non ancora attive. Servono dati meteo affidabili, account e consenso per ricevere avvisi.</p><span class="tag">Nessuna notifica verrà inviata</span></section><section class="card"><h2>I tuoi contributi di prova</h2><span class="stat">${reports.length}</span><p>Segnalazioni in questa sessione. Non contiamo persone protette o danni evitati senza poterlo verificare.</p></section><section class="card"><h2>Privacy e controllo</h2><p>Le preferenze dei luoghi restano nel browser. Non chiediamo la posizione GPS. I contenuti della demo non sono pubblici.</p><button id="reset" class="danger">Cancella le preferenze locali</button></section>`}
function shelters(){return `<h1>Ripari</h1><p>Informazioni pratiche, senza promesse di sicurezza.</p><section class="card empty"><div class="symbol">⌂</div><h2>Nessun riparo verificato disponibile</h2><p>Non mostriamo tettoie o posti liberi inventati. Accesso, orari, autorizzazioni e disponibilità dovranno essere controllati prima di elencare un luogo.</p></section><section class="card"><h2>Hai un suggerimento?</h2><p>Puoi provare a proporre un parcheggio coperto. Non apparirà come verificato.</p><form id="shelterForm"><label class="field"><span>Nome del luogo</span><input required maxlength="100" id="shelterName"></label><label class="field"><span>Informazioni utili</span><textarea required maxlength="400" placeholder="Zona e modalità di accesso, senza dati personali"></textarea></label><button class="button">Prova a proporre un luogo</button></form><p class="small">Solo simulazione: non viene inviata a un gestore.</p></section>`}
function render(){const focusKey=document.activeElement?.getAttribute('data-focus');const page=location.hash.slice(1)||'home';$('#app').innerHTML=({home,radar:radarView,segnala:reportView,community,mappa:()=>window.mapView?.(),profilo:profile,ripari:shelters}[page]||home)();$('#place').textContent=prefs.place+' ⌄';document.documentElement.style.fontSize=({normal:'100%',large:'118.75%',xl:'137.5%'}[prefs.textSize]||(prefs.large?'118.75%':'100%'));document.documentElement.classList.toggle('high-contrast',!!prefs.contrast);document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});bind();bindEnhancements();document.querySelectorAll('button,a,input,select,textarea,summary').forEach((el,i)=>el.dataset.focus='control-'+i);if(focusKey)document.querySelector('[data-focus="'+focusKey+'"]')?.focus({preventScroll:true});}

function accessDialog(){
 modal('Leggi SCUDO a modo tuo',`<label class="field"><span>Dimensione del testo</span><select id="textSize"><option value="normal">Normale</option><option value="large">Grande</option><option value="xl">Molto grande</option></select></label><label class="check"><input id="contrast" type="checkbox" ${prefs.contrast?'checked':''}><span>Contrasto più alto</span></label><label class="check"><input id="simple" type="checkbox" ${prefs.simple?'checked':''}><span>Modalità essenziale: meno dettagli nella home</span></label><p class="small">Preferenze solo su questo dispositivo. Puoi cambiarle quando vuoi.</p>`,()=>{prefs.textSize=$('#textSize').value;prefs.large=prefs.textSize!=='normal';prefs.contrast=$('#contrast').checked;prefs.simple=$('#simple').checked;save();render()});
 $('#textSize').value=prefs.textSize||(prefs.large?'large':'normal');
}
function inviteDialog(){
 modal('Un invito, scritto da te',`<div class="invite-preview"><b>SCUDO</b><h3>Il meteo è più utile, insieme.</h3><p>Un progetto per capire il meteo e confrontarsi con le persone della propria zona.</p><span class="tag">Prototipo · non un’allerta</span></div><label class="field"><span>Il messaggio che condividerai</span><textarea id="inviteText" maxlength="600">Sto provando SCUDO: un progetto di meteo semplice e community locale. È ancora una demo privata, non un servizio di allerta.</textarea></label><p class="small">Il link è privato. Chi lo riceve non ottiene automaticamente accesso. Puoi condividere solo il testo.</p><div class="invite-actions"><button type="button" id="nativeShare">Condividi messaggio</button><button type="button" id="copyInvite">Copia testo</button></div><p class="small" id="inviteStatus" role="status"></p>`,()=>{});
 $('#dialogForm button[type=submit]').textContent='Chiudi';
 $('#copyInvite').onclick=async()=>{try{await navigator.clipboard.writeText($('#inviteText').value);$('#inviteStatus').textContent='Testo copiato. Puoi incollarlo nella chat che scegli.'}catch{$('#inviteText').select();$('#inviteStatus').textContent='Copia non disponibile: seleziona e copia il testo manualmente.'}};
 $('#nativeShare').onclick=async()=>{if(!navigator.share){$('#inviteStatus').textContent='Condivisione non disponibile qui. Usa Copia testo.';return}try{await navigator.share({title:'SCUDO · Progetto in anteprima',text:$('#inviteText').value});$('#inviteStatus').textContent='Pannello di condivisione chiuso. Nessun destinatario viene tracciato.'}catch(e){$('#inviteStatus').textContent=e.name==='AbortError'?'Condivisione annullata.':'Condivisione non riuscita. Puoi copiare il testo.'}};
}
function bindEnhancements(){
 document.querySelectorAll('[data-access]').forEach(b=>b.onclick=()=>{accessDialog();$('#dialogForm button[type=submit]').textContent='Salva preferenze'});
 document.querySelectorAll('[data-invite]').forEach(b=>b.onclick=inviteDialog);
 document.querySelectorAll('[data-simple]').forEach(b=>b.onclick=()=>{prefs.simple=!prefs.simple;save();render();toast(prefs.simple?'Modalità essenziale attiva.':'Tutti i dettagli sono visibili.')});
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{if(!('speechSynthesis' in window)){toast('Lettura vocale non disponibile su questo browser.');return}if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();b.textContent='Ascolta il riepilogo';return}const u=new SpeechSynthesisUtterance('SCUDO. Prototipo con dati di esempio, non previsioni reali. Zona: '+prefs.place+'. Nell’esempio: ventidue gradi, parzialmente nuvoloso. Allerte e radar non collegati. Non usare questi dati per decisioni di sicurezza.');u.lang='it-IT';u.rate=.9;u.onend=()=>b.textContent='Ascolta il riepilogo';u.onerror=()=>{b.textContent='Ascolta il riepilogo';toast('La lettura vocale non è disponibile al momento.')};b.textContent='Ferma la lettura';window.speechSynthesis.speak(u)});
}

function bind(){document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-radar]').forEach(b=>b.onclick=()=>{radar=b.dataset.radar;render()});document.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{const id=+b.dataset.like;likes.has(id)?likes.delete(id):likes.add(id);render()});document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>{const id=+b.dataset.follow;following.has(id)?following.delete(id):following.add(id);render()});document.querySelectorAll('[data-comment]').forEach(b=>b.onclick=()=>modal('Aggiungi un commento di prova','<label class="field"><span>Commento</span><textarea id="comment" required maxlength="300"></textarea></label><p class="small">Visibile solo in questa sessione.</p>',()=>{const t=$('#comment').value.trim();if(!t)return false;(comments[b.dataset.comment]??=[]).push(t);render()}));document.querySelectorAll('[data-flag]').forEach(b=>b.onclick=()=>modal('Segnala un contenuto','<label class="field"><span>Motivo</span><select><option>Informazione potenzialmente falsa</option><option>Contenuto pericoloso</option><option>Dati personali</option><option>Spam o offese</option></select></label><p>Dimostrazione del flusso: non esiste ancora un servizio di moderazione attivo.</p>',()=>toast('Prova completata. Nessuna segnalazione inviata.')));
$('#reportForm')?.addEventListener('submit',e=>{e.preventDefault();const text=$('#description').value.trim(),area=$('#area').value.trim();if(!text||!area)return;reports.unshift({id:Date.now(),name:'Tu · prova locale',type:$('#kind').value,text,area,time:'Questa sessione'});filter='Tutti';location.hash='community';toast('Aggiunta solo alla tua sessione di prova.')});$('#addPlace')?.addEventListener('click',locationDialog);$('#large')?.addEventListener('change',e=>{prefs.large=e.target.checked;save();render()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{prefs.places.splice(+b.dataset.remove,1);save();render()});$('#reset')?.addEventListener('click',()=>modal('Cancellare le preferenze?','<p>Verranno rimossi i luoghi e le impostazioni di lettura salvati su questo dispositivo.</p>',()=>{prefs={place:'Porto d’Ascoli',places:['Porto d’Ascoli'],large:false};save();render();toast('Preferenze ripristinate.')}));$('#shelterForm')?.addEventListener('submit',e=>{e.preventDefault();e.target.reset();toast('Proposta di prova completata. Nessun luogo pubblicato.')});$('#share')?.addEventListener('click',async()=>{const text='SCUDO: prototipo di meteo e community locale. Dati dimostrativi, anteprima privata.';try{if(navigator.share)await navigator.share({title:'SCUDO',text,url:location.origin});else if(navigator.clipboard){await navigator.clipboard.writeText(text+' '+location.origin);toast('Link copiato. Non concede accesso all’anteprima privata.')}else toast('La condivisione non è disponibile in questo browser.')}catch(e){if(e.name!=='AbortError')toast('Condivisione non riuscita.')}})}
window.addEventListener('hashchange',()=>{window.speechSynthesis?.cancel();render();const heading=$('#app h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}window.scrollTo(0,0)});render();


